import{_ as a,o as i,c as e,ag as o}from"./chunks/framework.DzGOF12C.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Phenomenology/01. 서론.md","filePath":"philosophy/Phenomenology/01. 서론.md"}'),t={name:"philosophy/Phenomenology/01. 서론.md"};function r(n,l,h,s,_,d){return i(),e("div",null,[...l[0]||(l[0]=[o('<h2 id="현상학" tabindex="-1">현상학 <a class="header-anchor" href="#현상학" aria-label="Permalink to &quot;현상학&quot;">​</a></h2><p>현상을 탐구하는 학문</p><ol><li>현상에 대한 탐구</li><li>이를 학문의 기본적인 토대로 간주하는 철학적 사조</li></ol><h2 id="현상" tabindex="-1">현상: <a class="header-anchor" href="#현상" aria-label="Permalink to &quot;현상:&quot;">​</a></h2><p>객관적 대상, 실제 대상, 실재에 대립하여 대상이 주체에게 나타나는 모습 + 나타남 자체<br> -&gt; 주관적 경험, 의식에 관한 탐구</p><h3 id="왜-필요한가" tabindex="-1">왜 필요한가? <a class="header-anchor" href="#왜-필요한가" aria-label="Permalink to &quot;왜 필요한가?&quot;">​</a></h3><p>현상은 실재로 존재하지 않는데 왜 필요한가요?</p><ol><li>현상은 실재에 대한 모든 앎의 근원<br> 대상이 나에게 나타남으로써 대상이 어떠한지를 알 수 있음<br> 나에게 직간접적으로 나타나지 않으면, 대상에 관해 알 수 없음</li><li>현상은 우리에게 가장 밀접하고 확실한 것<br> 대상이 실제로 있다는 것 등등.. 의심가능 하지만, 현상이 나타남은 의심할 수 없음</li><li>삶에서 가장 중요한 것으로 여겨질 수 있음<br> 사실 일상에서 우리가 관심을 가지는 것은 실재 자체보다 대상이 나에게 나타나는 모습에 관심을 가짐</li></ol><h3 id="현상학의-의의" tabindex="-1">현상학의 의의 <a class="header-anchor" href="#현상학의-의의" aria-label="Permalink to &quot;현상학의 의의&quot;">​</a></h3><ul><li>의식을 연구하기 위한 체계적 개념과 방법, 구체적 연구를 제공</li><li>새로운 제일철학의 가능성 암시</li><li>자연주의와 과학주의에 대한 강력한 비판 <ul><li>자연과학을 통해 모든 것을 설명할 수 없다!</li></ul></li><li>생활세계의 복권(復權) <ul><li><strong>생활세계:</strong> 학문으로 밝혀지기 이전 일상적으로 경험하는 세계</li><li>객관적 세계는 결국 생활세계를 토대로 성립할 수 있다. (생활세계를 다듬는 방식으로)</li></ul></li><li>다양한 학문 분야에 새로운 통찰과 방법을 제공 <ul><li>현상학을 토대로, 현상학적 방법을 이용</li></ul></li></ul>',10)])])}const u=a(t,[["render",r]]);export{c as __pageData,u as default};
